// Rows x 1 channel per thread; every output keeps the reference K8 order.
uint index = thread_position_in_grid.x;
int row0 = int(index / uint(N)) * Rows, channel = int(index % uint(N));
if (row0 >= M) return;
bool reference = special[0] != 0;
auto xs = x + KOffset;
auto ws = w + channel * Ldw + KOffset;
float partial0[Rows], partial1[Rows];
for (int i = 0; i < Rows; ++i) partial0[i] = partial1[i] = 0.0f;
if (Sliced) {
    // Each 64-wide K tile feeds blocks 0-3 to partial0 and 4-7 to partial1.
    for (int tile = 0; tile < K / 8; tile += 8) {
        nv_blocks<Rows>(partial0, tile, tile + 4, reference, xs, Ldx, row0, M, ws);
        nv_blocks<Rows>(partial1, tile + 4, tile + 8, reference, xs, Ldx, row0, M, ws);
    }
} else {
    nv_blocks<Rows>(partial0, 0, K / 8, reference, xs, Ldx, row0, M, ws);
}
for (int i = 0; i < Rows && row0 + i < M; ++i) {
    int output_index = (row0 + i) * N + channel;
    float carry = Sliced ? partial0[i] + partial1[i] : partial0[i];
    if (HasC) carry = carry + c[output_index];
    if (HasBias) carry = carry + bias[channel];
    uint bits = as_type<uint>(carry);
    bits = (bits + 0x7fff + ((bits >> 16) & 1)) & 0xffff0000;
    output[output_index] = as_type<float>(bits);
}

projection.header:
METAL_FUNC int nv_align(float value, int common) {
    uint bits = as_type<uint>(value);
    if ((bits & 0x7fffffff) == 0) return 0;
    int exponent = int((bits >> 23) & 255) - 127;
    uint mantissa = (bits & 0x7fffff) | 0x800000;
    int shift = exponent - 23 - common;
    uint aligned = shift >= 0 ? mantissa << shift :
        (-shift < 32 ? mantissa >> (-shift) : 0);
    return (bits >> 31) ? -int(aligned) : int(aligned);
}
METAL_FUNC float nv_block(float carry, thread float* x, thread float* w) {
    int maximum = -1000;
    uint carry_bits = as_type<uint>(carry);
    if (carry_bits & 0x7fffffff) maximum = int((carry_bits >> 23) & 255) - 127;
    float products[8];
    for (int k = 0; k < 8; ++k) {
        uint xb = as_type<uint>(x[k]), wb = as_type<uint>(w[k]);
        products[k] = x[k] * w[k];
        if ((xb & 0x7fffffff) && (wb & 0x7fffffff)) {
            int raw_exponent = int((xb >> 23) & 255) + int((wb >> 23) & 255) - 254;
            maximum = max(maximum, raw_exponent);
        }
    }
    if (maximum == -1000) return 0.0f;
    int common = maximum - 24;
    int sum = nv_align(carry, common);
    for (int k = 0; k < 8; ++k) sum += nv_align(products[k], common);
    if (!sum) return 0.0f;
    uint magnitude = sum < 0 ? uint(-sum) : uint(sum);
    int shift = max(0, int(31 - clz(magnitude)) - 23);
    int truncated = int(magnitude >> shift);
    if (sum < 0) truncated = -truncated;
    return ldexp(float(truncated), common + shift);
}

METAL_FUNC void nv_load8(const device bfloat16_t* source, thread float* v) {
    uint4 u = *(const device uint4*)source;
    v[0] = as_type<float>(u.x << 16); v[1] = as_type<float>(u.x & 0xffff0000u);
    v[2] = as_type<float>(u.y << 16); v[3] = as_type<float>(u.y & 0xffff0000u);
    v[4] = as_type<float>(u.z << 16); v[5] = as_type<float>(u.z & 0xffff0000u);
    v[6] = as_type<float>(u.w << 16); v[7] = as_type<float>(u.w & 0xffff0000u);
}
METAL_FUNC void nv_load8(const device float* source, thread float* v) {
    float4 a = *(const device float4*)source, b = *(const device float4*)(source + 4);
    v[0] = a.x; v[1] = a.y; v[2] = a.z; v[3] = a.w;
    v[4] = b.x; v[5] = b.y; v[6] = b.z; v[7] = b.w;
}
METAL_FUNC float nv_power(float value) {
    return as_type<float>(as_type<uint>(value) & 0x7f800000u);
}
// Exact nv_block for operands without inf, NaN or subnormals. 2^ex * 2^ew is
// then the exact pair exponent: zero pairs give 0 and out-of-range pairs
// underflow or overflow, which the [2^-100, 2^125] window sends to nv_block.
// Inside it nv_align(v, common) == trunc(v * 2^-common): the scale is a normal
// power of two, terms stay below 2^27, and subnormal products and carries align
// to zero in both formulations.
METAL_FUNC float nv_block_lean(
    float carry, thread float* x, thread float* xp, thread float* w, thread float* wp) {
    float peak = nv_power(carry);
    for (int k = 0; k < 8; ++k) peak = max(peak, xp[k] * wp[k]);
    if (!(peak >= 0x1p-100f && peak <= 0x1p125f)) return nv_block(carry, x, w);
    uint field = as_type<uint>(peak) >> 23;
    float scale = as_type<float>((278u - field) << 23);
    int common = int(field) - 151;
    int sum = int(carry * scale);
    for (int k = 0; k < 8; ++k) sum += int((x[k] * w[k]) * scale);
    if (!sum) return 0.0f;
    uint magnitude = sum < 0 ? uint(-sum) : uint(sum);
    int shift = max(0, int(31 - clz(magnitude)) - 23);
    int truncated = int(magnitude >> shift);
    if (sum < 0) truncated = -truncated;
    return ldexp(float(truncated), common + shift);
}
// Applies K8 blocks [first, last) to Rows consecutive rows of one channel.
template <int Rows, typename X, typename W>
METAL_FUNC void nv_blocks(
    thread float* carry, int first, int last, bool reference,
    const device X* x, int ldx, int row0, int rows, const device W* w) {
    for (int b = first; b < last; ++b) {
        float wv[8], wp[8];
        nv_load8(w + b * 8, wv);
        for (int k = 0; k < 8; ++k) wp[k] = nv_power(wv[k]);
        for (int i = 0; i < Rows; ++i) {
            float xv[8], xp[8];
            nv_load8(x + min(row0 + i, rows - 1) * ldx + b * 8, xv);
            for (int k = 0; k < 8; ++k) xp[k] = nv_power(xv[k]);
            carry[i] = reference ? nv_block(carry[i], xv, wv)
                                 : nv_block_lean(carry[i], xv, xp, wv, wp);
        }
    }
}

operand_check.source:
// Flags inf, NaN or subnormal operands; their projections use nv_block throughout.
uint index = thread_position_in_grid.x;
if (index >= uint(Count)) return;
uint bits = nv_bits(values[index]);
uint field = bits & 0x7f800000u;
if (field == 0x7f800000u || (field == 0 && (bits & 0x7fffffffu)))
    atomic_store_explicit(&special[0], 1u, memory_order_relaxed);

