uint lane = thread_position_in_threadgroup.x;
uint row_local = thread_position_in_threadgroup.y;
uint row = threadgroup_position_in_grid.y * 4 + row_local;
threadgroup float partial[4 * (Lanes + 1)];
float carry = 0.0f;
uint chunk = K / Lanes;
if (row < N) {
    for (uint j = 0; j < chunk; ++j) {
        uint k = lane + j * Lanes;
        carry = fma(float(weight[row * K + k]), float(input[k]), carry);
    }
}
uint local = row_local * (Lanes + 1) + lane;
partial[local] = carry;
for (uint span = Lanes / 2; span > 0; span /= 2) {
    threadgroup_barrier(mem_flags::mem_threadgroup);
    if (lane < span) {
        volatile float combined = partial[local] + partial[local + span];
        partial[local] = combined;
    }
}
threadgroup_barrier(mem_flags::mem_threadgroup);
if (lane == 0 && row < N) {
    volatile float combined = fma(1.0f, partial[local], 0.0f);
    combined = combined + 0.0f;
    uint bits = as_type<uint>(combined);
    bits = (bits + 0x7fff + ((bits >> 16) & 1)) & 0xffff0000;
    output[row] = as_type<float>(bits);
}

mean.source:
uint index = thread_position_in_grid.x;
uint row = index / Lanes, lane = index % Lanes;
if (row >= uint(Rows)) return;
volatile float p0 = 0.0f, p1 = 0.0f, p2 = 0.0f, p3 = 0.0f;
for (uint vector = lane; vector < uint(Width / 4); vector += Lanes) {
    uint start = row * Width + vector * 4;
    p0 = p0 + square[start];
    p1 = p1 + square[start + 1];
    p2 = p2 + square[start + 2];
    p3 = p3 + square[start + 3];
}
volatile float combined = p0 + p1;
combined = combined + p2;
combined = combined + p3;
float value = combined;
threadgroup float partial[Lanes];
partial[lane] = value;
for (uint offset = Lanes / 2; offset >= 32; offset >>= 1) {
    threadgroup_barrier(mem_flags::mem_threadgroup);
    if (lane < offset) {
        value = value + partial[lane + offset];
        partial[lane] = value;
    }
}
threadgroup_barrier(mem_flags::mem_threadgroup);
for (ushort offset = 16; offset > 0; offset >>= 1) {
    value = value + simd_shuffle_down(value, offset);
}
if (lane == 0) output[row] = value * as_type<float>(uint(FactorBits));

