rsqrt.source:
uint i = thread_position_in_grid.x;
if (i >= uint(Count)) return;
float value = values[i];
uint bits = as_type<uint>(value);
int exponent = int((bits >> 23) & 255);
if ((bits & 0x80000000u) || exponent == 0 || exponent == 255) {
    output[i] = metal::precise::rsqrt(value);
    return;
}
int unbiased = exponent - 127;
int half_exponent = (unbiased - (unbiased & 1)) / 2;
uint index = (bits & 0x7fffffu) | (uint(unbiased & 1) << 23);
uint result = uint(int(unary_table[index]) - half_exponent * 8388608);
output[i] = as_type<float>(result);

exp.header:
uint unit_index(uint key, device const uint* threshold) {
    uint low = 0, high = 8388609;
    while (low < high) {
        uint middle = low + ((high - low) >> 1);
        if (threshold[middle] <= key) low = middle + 1;
        else high = middle;
    }
    return low - 1;
}

float nv_mufu_exp2(float value, device const uint* positive, device const uint* negative, device const uint* direct) {
    uint bits = as_type<uint>(value), magnitude = bits & 0x7fffffff;
    if (bits >> 31) {
        if (magnitude <= 0x3f800000) {
            return as_type<float>(0x3f800000 - unit_index(magnitude, negative));
        }
        if (magnitude <= 0x43000000) return as_type<float>(direct[magnitude - 0x3f800000]);
        if (magnitude <= 0x7f800000) return 0.0f;
    } else if (magnitude <= 0x3f800000) {
        return as_type<float>(0x3f800000 + unit_index(magnitude, positive));
    }
    // Outside the independently verified raw-MUFU domain.
    return metal::precise::exp2(value);
}

float nv_exp(float value, device const uint* positive, device const uint* negative, device const uint* direct) {
    if (isnan(value) || value > 80.0f) return metal::precise::exp(value);
    float fraction = clamp(fma(value, as_type<float>(uint(0x3bbb989d)), 0.5f), 0.0f, 1.0f);
    uint fb = as_type<uint>(fraction), fe = (fb >> 23) & 255;
    uint shift = 150 - fe;
    // Original FFMA.RM at the magic integer computes floor(fraction*252).
    uint integer = (fe == 0 || shift >= 32) ? 0 : (((fb & 0x7fffff) | 0x800000) * 252u) >> shift;
    int exponent = int(integer) - 126;
    float residual = fma(value, as_type<float>(uint(0x3fb8aa3b)), -float(exponent));
    residual = fma(value, as_type<float>(uint(0x32a57060)), residual);
    uint output_bits = as_type<uint>(nv_mufu_exp2(residual, positive, negative, direct));
    if (output_bits == 0) return 0.0f;
    int output_exponent = int((output_bits >> 23) & 255) + exponent;
    if (output_exponent >= 255) return INFINITY;
    if (output_exponent > 0) return as_type<float>(uint(int(output_bits) + exponent * 8388608));
    uint significand = (output_bits & 0x7fffff) | 0x800000;
    uint right = uint(1 - output_exponent);
    if (right > 24) return 0.0f;
    uint retained = significand >> right;
    uint tail = significand & ((1u << right) - 1);
    uint halfway = 1u << (right - 1);
    if (tail > halfway || (tail == halfway && (retained & 1))) retained++;
    return as_type<float>(retained);
}

log1p.header:
float source_positive_log1p(float a) {
    uint ab = as_type<uint>(a);
    if (ab < 0x00800000) return a; // log1p positive subnormals rounds to input.
    if (ab >= 0x7f800000) return metal::precise::log(1.0f + a);
    // Positive round-toward-zero addition, independent of the polynomial.
    volatile float rounded = a + 1.0f;
    volatile float residual = a >= 1.0f ? (a - rounded) + 1.0f : (1.0f - rounded) + a;
    uint rb = as_type<uint>(rounded);
    if (residual < 0.0f) rb--;
    int scale = int((rb - 1061158912u) & 0xff800000u);
    float scaled_a = as_type<float>(uint(int(ab) - scale));
    float power = as_type<float>(uint(1082130432 - scale));
    volatile float t = scaled_a + fma(0.25f, power, -1.0f);
    float n = float(scale) * 0x1p-23f;
    float p = fma(as_type<float>(uint(0xbd39bf78)), t, as_type<float>(uint(0x3dd80012)));
    p = fma(p, t, as_type<float>(uint(0xbe0778e0)));
    p = fma(p, t, as_type<float>(uint(0x3e146475)));
    p = fma(p, t, as_type<float>(uint(0xbe2a68dd)));
    p = fma(p, t, as_type<float>(uint(0x3e4caf9e)));
    p = fma(p, t, as_type<float>(uint(0xbe800042)));
    p = fma(p, t, as_type<float>(uint(0x3eaaaae6)));
    p = fma(p, t, -0.5f);
    volatile float product = p * t;
    p = fma(product, t, t);
    return fma(n, as_type<float>(uint(0x3f317218)), p);
}

triangle_sum.source:
uint index = thread_position_in_grid.x;
if (index >= uint(Outputs)) return;
uint column = index % Width;
uint start = (index / Width) * Width * Width + column;
volatile float p0 = 0.0f, p1 = 0.0f, p2 = 0.0f, p3 = 0.0f;
for (uint i = 0; i < uint(Width); i += 4) {
    p0 = gradual_add(p0, product[start + i * Width]);
    if (i + 1 < uint(Width)) p1 = gradual_add(p1, product[start + (i + 1) * Width]);
    if (i + 2 < uint(Width)) p2 = gradual_add(p2, product[start + (i + 2) * Width]);
    if (i + 3 < uint(Width)) p3 = gradual_add(p3, product[start + (i + 3) * Width]);
}
volatile float combined = gradual_add(p0, p1);
combined = gradual_add(combined, p2);
combined = gradual_add(combined, p3);
output[index] = combined;

triangle_sum.header:
float gradual_add(float a, float b) {
    uint ab = as_type<uint>(a), bb = as_type<uint>(b);
    uint ae = (ab >> 23) & 255, be = (bb >> 23) & 255;
    float ordinary = a + b;
    uint rb = as_type<uint>(ordinary), re = (rb >> 23) & 255;
    if ((ae == 0 || be == 0 || re == 0) && ae <= 64 && be <= 64) {
        // Exact power-of-two rescaling keeps every subnormal input normal on Metal.
        float sa = ae == 0 ? float(ab & 0x7fffff) * 0x1p-85f : as_type<float>(ab + (64u << 23));
        float sb = be == 0 ? float(bb & 0x7fffff) * 0x1p-85f : as_type<float>(bb + (64u << 23));
        if (ae == 0 && (ab >> 31)) sa = -sa;
        if (be == 0 && (bb >> 31)) sb = -sb;
        uint scaled = as_type<uint>(sa + sb);
        uint exponent = (scaled >> 23) & 255;
        uint sign = scaled & 0x80000000;
        if ((scaled & 0x7fffffff) == 0) return as_type<float>(sign);
        if (exponent > 64) return as_type<float>(scaled - (64u << 23));
        uint significand = (scaled & 0x7fffff) | 0x800000;
        uint shift = 65 - exponent;
        uint retained = significand >> shift;
        uint mask = (1u << shift) - 1;
        uint tail = significand & mask;
        uint halfway = 1u << (shift - 1);
        if (tail > halfway || (tail == halfway && (retained & 1))) retained++;
        return as_type<float>(sign | retained);
    }
    return ordinary;
}

activation.source:
uint i = thread_position_in_grid.x;
if (i >= uint(Count)) return;
float value = values[i];
uint bits = as_type<uint>(value);
uint exponent = (bits >> 23) & 255;
if ((bits & 65535u) == 0 && exponent != 255) {
    uint result = unary_table[bits >> 16];
    if (Sigmoid) result <<= 16;
    output[i] = as_type<float>(result);
} else {
    output[i] = Sigmoid ? 1.0f / (1.0f + metal::precise::exp(-value)) : value / (1.0f + metal::precise::exp(-value));
}

