uint index = thread_position_in_grid.x;
if (index >= 4096) return;
uint head = index / 128, column = index % 128;
float state[128];
for (uint k = 0; k < 128; ++k) {
    volatile float decayed = initial[(head*128+k)*128+column] * decay[head];
    state[k] = decayed;
}
float reduced[4];
for (uint lane = 0; lane < 4; ++lane) {
    volatile float p0=0.0f,p1=0.0f,p2=0.0f,p3=0.0f;
    for (uint k=lane;k<128;k+=16) {
        volatile float a=state[k]*key[(head/Ratio)*128+k];
        volatile float b=state[k+4]*key[(head/Ratio)*128+k+4];
        volatile float c=state[k+8]*key[(head/Ratio)*128+k+8];
        volatile float d=state[k+12]*key[(head/Ratio)*128+k+12];
        p0=p0+a;p1=p1+b;p2=p2+c;p3=p3+d;
    }
    volatile float merged=p0+p1;merged=merged+p2;merged=merged+p3;
    reduced[lane]=merged;
}
volatile float left=reduced[0]+reduced[2];
volatile float right=reduced[1]+reduced[3];
volatile float memory=left+right;

volatile float difference=value[head*128+column]-memory;
volatile float delta=difference*beta[head];
for (uint k=0;k<128;++k) {
    volatile float product=key[(head/Ratio)*128+k]*delta;
    volatile float updated=state[k]+product;
    state[k]=updated;
    final_state[(head*128+k)*128+column]=updated;
}
for (uint lane = 0; lane < 4; ++lane) {
    volatile float p0=0.0f,p1=0.0f,p2=0.0f,p3=0.0f;
    for (uint k=lane;k<128;k+=16) {
        volatile float a=state[k]*query[(head/Ratio)*128+k];
        volatile float b=state[k+4]*query[(head/Ratio)*128+k+4];
        volatile float c=state[k+8]*query[(head/Ratio)*128+k+8];
        volatile float d=state[k+12]*query[(head/Ratio)*128+k+12];
        p0=p0+a;p1=p1+b;p2=p2+c;p3=p3+d;
    }
    volatile float merged=p0+p1;merged=merged+p2;merged=merged+p3;
    reduced[lane]=merged;
}
