using namespace mlx::steel;
struct NvMaxOp {template<typename T> METAL_FUNC static T apply(T a,T b){return metal::max(a,b);}};
struct NvSumOp {template<typename T> METAL_FUNC static T apply(T a,T b){return a+b;}};
struct NvMulOp {template<typename T> METAL_FUNC static T apply(T a,T b){return a*b;}};
struct NvDivOp {template<typename T> METAL_FUNC static T apply(T a,T b){return a/b;}};

METAL_FUNC int nv_align(float value, int common) {
    uint bits = as_type<uint>(value);
    if ((bits & 0x7fffffff) == 0) return 0;
    int exponent = int((bits >> 23) & 255) - 127;
    uint mantissa = (bits & 0x7fffff) | 0x800000;
    int shift = exponent - 23 - common;
    uint aligned = shift >= 0 ? mantissa << shift :
        (-shift < 32 ? mantissa >> (-shift) : 0);
    return (bits >> 31) ? -int(aligned) : int(aligned);
}
METAL_FUNC float nv_block_reference(float carry, thread float* x, thread float* w) {
    int maximum = -1000;
    uint carry_bits = as_type<uint>(carry);
    if (carry_bits & 0x7fffffff) maximum = int((carry_bits >> 23) & 255) - 127;
    float products[8];
    for (int k = 0; k < 8; ++k) {
        uint xb = as_type<uint>(x[k]), wb = as_type<uint>(w[k]);
        products[k] = x[k] * w[k];
        if ((xb & 0x7fffffff) && (wb & 0x7fffffff)) {
            int raw_exponent = int((xb >> 23) & 255) + int((wb >> 23) & 255) - 254;
            maximum = max(maximum, raw_exponent);
        }
    }
    if (maximum == -1000) return 0.0f;
    int common = maximum - 24;
    int sum = nv_align(carry, common);
    for (int k = 0; k < 8; ++k) sum += nv_align(products[k], common);
    if (!sum) return 0.0f;
    uint magnitude = sum < 0 ? uint(-sum) : uint(sum);
    int shift = max(0, int(31 - clz(magnitude)) - 23);
    int truncated = int(magnitude >> shift);
    if (sum < 0) truncated = -truncated;
    return ldexp(float(truncated), common + shift);
}

METAL_FUNC float nv_power(float value) {
    return as_type<float>(as_type<uint>(value) & 0x7f800000u);
}
// Exact nv_block for operands without inf, NaN or subnormals. 2^ex * 2^ew is
// then the exact pair exponent: zero pairs give 0 and out-of-range pairs
// underflow or overflow, which the [2^-100, 2^125] window sends to the reference block.
// Inside it nv_align(v, common) == trunc(v * 2^-common): the scale is a normal
// power of two, terms stay below 2^27, and subnormal products and carries align
// to zero in both formulations.
METAL_FUNC float nv_block_lean(
    float carry, thread float* x, thread float* xp, thread float* w, thread float* wp) {
    float peak = nv_power(carry);
    for (int k = 0; k < 8; ++k) peak = max(peak, xp[k] * wp[k]);
    if (!(peak >= 0x1p-100f && peak <= 0x1p125f)) return nv_block_reference(carry, x, w);
    uint field = as_type<uint>(peak) >> 23;
    float scale = as_type<float>((278u - field) << 23);
    int common = int(field) - 151;
    int sum = int(carry * scale);
    for (int k = 0; k < 8; ++k) sum += int((x[k] * w[k]) * scale);
    if (!sum) return 0.0f;
    uint magnitude = sum < 0 ? uint(-sum) : uint(sum);
    int shift = max(0, int(31 - clz(magnitude)) - 23);
    int truncated = int(magnitude >> shift);
    if (sum < 0) truncated = -truncated;
    return ldexp(float(truncated), common + shift);
}

// Attention forms BF16 probability tiles on device; classify each local K8
// block before using the same exact alignment window as projection.
METAL_FUNC float nv_block(float carry, thread float* x, thread float* w) {
    float xp[8], wp[8];
    bool regular = true;
    for (int k = 0; k < 8; ++k) {
        uint xb = as_type<uint>(x[k]) & 0x7fffffffu;
        uint wb = as_type<uint>(w[k]) & 0x7fffffffu;
        regular = regular && (xb == 0 || (xb >= 0x00800000u && xb < 0x7f800000u));
        regular = regular && (wb == 0 || (wb >= 0x00800000u && wb < 0x7f800000u));
        xp[k] = nv_power(x[k]);
        wp[k] = nv_power(w[k]);
    }
    return regular ? nv_block_lean(carry, x, xp, w, wp) : nv_block_reference(carry, x, w);
}

uint unit_index(uint key, device const uint* threshold) {
    uint low = 0, high = 8388609;
    while (low < high) {
        uint middle = low + ((high - low) >> 1);
        if (threshold[middle] <= key) low = middle + 1;
        else high = middle;
    }
    return low - 1;
}

float nv_mufu_exp2(float value, device const uint* positive, device const uint* negative, device const uint* direct) {
    uint bits = as_type<uint>(value), magnitude = bits & 0x7fffffff;
    if (bits >> 31) {
        if (magnitude <= 0x3f800000) {
            return as_type<float>(0x3f800000 - unit_index(magnitude, negative));
        }
        if (magnitude <= 0x43000000) return as_type<float>(direct[magnitude - 0x3f800000]);
        if (magnitude <= 0x7f800000) return 0.0f;
    } else if (magnitude <= 0x3f800000) {
        return as_type<float>(0x3f800000 + unit_index(magnitude, positive));
    }
    // Outside the independently verified raw-MUFU domain.
    return metal::precise::exp2(value);
}

float nv_exp(float value, device const uint* positive, device const uint* negative, device const uint* direct) {
    if (isnan(value) || value > 80.0f) return metal::precise::exp(value);
    float fraction = clamp(fma(value, as_type<float>(uint(0x3bbb989d)), 0.5f), 0.0f, 1.0f);
    uint fb = as_type<uint>(fraction), fe = (fb >> 23) & 255;
    uint shift = 150 - fe;
    // Original FFMA.RM at the magic integer computes floor(fraction*252).
    uint integer = (fe == 0 || shift >= 32) ? 0 : (((fb & 0x7fffff) | 0x800000) * 252u) >> shift;
    int exponent = int(integer) - 126;
    float residual = fma(value, as_type<float>(uint(0x3fb8aa3b)), -float(exponent));
    residual = fma(value, as_type<float>(uint(0x32a57060)), residual);
    uint output_bits = as_type<uint>(nv_mufu_exp2(residual, positive, negative, direct));
    if (output_bits == 0) return 0.0f;
    int output_exponent = int((output_bits >> 23) & 255) + exponent;
    if (output_exponent >= 255) return INFINITY;
    if (output_exponent > 0) return as_type<float>(uint(int(output_bits) + exponent * 8388608));
    uint significand = (output_bits & 0x7fffff) | 0x800000;
    uint right = uint(1 - output_exponent);
    if (right > 24) return 0.0f;
    uint retained = significand >> right;
    uint tail = significand & ((1u << right) - 1);
    uint halfway = 1u << (right - 1);
    if (tail > halfway || (tail == halfway && (retained & 1))) retained++;
    return as_type<float>(retained);
}

METAL_FUNC float nv_separate_argument(float score, float scale, float maximum) {
    volatile float maximum_scaled = maximum * scale;
    volatile float score_scaled = score * scale;
    return score_scaled - maximum_scaled;
}

split_attention.source:
using Frag = BaseMMAFrag<float,8,8>;
const uint lane=thread_index_in_simdgroup;
const uint group=simdgroup_index_in_threadgroup;
uint3 tid=threadgroup_position_in_grid;
const int splits=meta[5];
const int split=int(tid.z)%splits;
const int batch=int(tid.z)/splits;
tid.z=batch;
const short2 coordinate=Frag::get_coord(lane);
const int sm=coordinate.y, sn=coordinate.x;
const int qlen=meta[0], klen=meta[1], heads=meta[2], kvheads=meta[3], offset=meta[4];
const int qb=int(tid.x)*32+int(group)*8;
const int kh=int(tid.y)/(heads/kvheads);
const device T* Q=q+(tid.z*heads+tid.y)*qlen*D;
const device T* K=k+(tid.z*kvheads+kh)*klen*D;
const device T* V=v+(tid.z*kvheads+kh)*klen*D;
device float* O=output+((split*meta[6]+batch)*heads+tid.y)*qlen*D+qb*D;
MMATile<float,1,8,Frag> scores;
MMATile<float,1,D/8,Frag> accum;
accum.clear();
float maximum[1]={-MAXFLOAT}, denominator[1]={0};
int last=(klen+63)/64-1;
if(Causal) last=min(last,(offset+min(qb+8,qlen)+63)/64-1);
const float scale=scalar_scale;
const int per_split=((klen+63)/64+splits-1)/splits;
const int first=split*per_split;
last=min(last,first+per_split-1);
for(int iteration=0;iteration<=last-first;++iteration){
    int tile=last-iteration;
    const int kb=tile*64;
    scores.clear();


    for(int j=0;j<8;++j){
        for(int c=0;c<2;++c){
            const int row=qb+sm, column=kb+j*8+sn+c;
            float score=0.0f;
            for(int start=0;start<D;start+=8){
                float xv[8],wv[8];
                for(int channel=0;channel<8;++channel){
                    xv[channel]=row<qlen ? float(Q[row*D+start+channel]) : 0.0f;
                    wv[channel]=column<klen ? float(K[column*D+start+channel]) : 0.0f;
                }
                score=nv_block(score,xv,wv);
            }
            scores.frag_at(0,j)[c]=score;
        }
    }

    for(int j=0;j<8;++j){
        for(int c=0;c<2;++c){
            int column=kb+j*8+sn+c;
            int row=qb+sm;
            if(column>=klen || row>=qlen || (Causal && column>offset+row))scores.frag_at(0,j)[c]=-MAXFLOAT;
        }
    }
    float newmax[1]={maximum[0]};
    scores.template row_reduce<NvMaxOp>(newmax);
    const float factor=nv_mufu_exp2((maximum[0]-newmax[0])*scale,positive,negative,direct);
    for(int j=0;j<8;++j){
        for(int c=0;c<2;++c){
            float s=scores.frag_at(0,j)[c];
            scores.frag_at(0,j)[c]=nv_mufu_exp2(nv_separate_argument(s,scale,newmax[0]),positive,negative,direct);
        }
    }

    denominator[0] = metal::fma(denominator[0], factor, scores.frag_at(0,0)[0]);
    denominator[0] += scores.frag_at(0,0)[1];
    for(int j=1;j<8;++j){
        for(int c=0;c<2;++c)denominator[0] += scores.frag_at(0,j)[c];
    }

    float factors[1]={factor};
    accum.template row_bin_op<NvMulOp>(factors);
    maximum[0]=newmax[0];
    for(int j=0;j<8;++j){
        for(int c=0;c<2;++c)scores.frag_at(0,j)[c]=float(T(scores.frag_at(0,j)[c]));
    }


    for(int dd=0;dd<D/8;++dd){
        for(int c=0;c<2;++c){
            float carry=accum.frag_at(0,dd)[c];
            const int column=dd*8+sn+c;
            for(int j=0;j<8;++j){
                float probabilities[8],values[8];
                for(int key=0;key<8;++key){
                    // MLX fragment rows share lanes whose bits 0 and 3 select
                    // two-column pairs. Source K8 consumes keys in order.
                    const ushort source_lane=ushort((lane&~9u)|uint((key>>1)&1)|uint(((key>>2)&1)*8));
                    probabilities[key]=simd_shuffle(scores.frag_at(0,j)[key&1],source_lane);
                    const int row=kb+j*8+key;
                    values[key]=row<klen ? float(V[row*D+column]) : 0.0f;
                }
                carry=nv_block(carry,probabilities,values);
            }
            accum.frag_at(0,dd)[c]=carry;
        }
    }


}
denominator[0] += simd_shuffle_xor(denominator[0],ushort(8));
denominator[0] += simd_shuffle_xor(denominator[0],ushort(1));
float inverse_sum[1]={
    (denominator[0]==0.0f || metal::isnan(denominator[0])) ? 1.0f : 1.0f/denominator[0]
};
accum.template row_bin_op<NvMulOp>(inverse_sum);
if(qb<qlen)accum.template store_safe<float,1,1>(O+sm*D+sn,D,short2(D-sn,qlen-qb-sm));

