float nv_cached_combine_logf(float value) {
    uint bits=as_type<uint>(value);
    if (bits < 0x3f800000u || bits > 0x42800000u) return metal::precise::log(value);
    int exponent_bits=int((bits-0x3f2aaaabu)&0xff800000u);
    volatile float fraction=as_type<float>(uint(int(bits)-exponent_bits))-1.0f;
    float exponent=float(exponent_bits)*0x1p-23f;
    float p=fma(fraction,-as_type<float>(uint(0x3e055027)),0.14084610342979431152f);
    p=fma(fraction,p,-0.12148627638816833496f);
    p=fma(fraction,p,0.13980610668659210205f);
    p=fma(fraction,p,-0.16684235632419586182f);
    p=fma(fraction,p,0.20012299716472625732f);
    p=fma(fraction,p,-0.24999669194221496582f);
    p=fma(fraction,p,0.33333182334899902344f);
    p=fma(fraction,p,-0.5f);
    volatile float product=fraction*p;
    p=fma(fraction,product,fraction);
    return fma(exponent,as_type<float>(uint(0x3f317218)),p);
}

split_combine.source:
uint index=thread_position_in_grid.x;
if(index>=4096)return;
uint head=index/256;
float carry=0.0f;
for(uint split=0;split<Splits;split++) {
    carry=fma(scales[split*16+head],parts[split*4096+index],carry);
}
output[index]=carry;

layernorm_statistics.source:
uint row = threadgroup_position_in_grid.x;
uint lane = thread_position_in_threadgroup.x % 32;
uint warp = thread_position_in_threadgroup.x / 32;
uint tid = thread_position_in_threadgroup.x;
threadgroup float means[4], sigmas[4], counts[4];
Welford value{0.0f, 0.0f, 0.0f};
for (uint vector = tid; vector < uint(Width / 4); vector += 128) {
    for (uint component = 0; component < 4; component++) {
        float element = values[row * Width + vector * 4 + component];
        volatile float delta = element - value.mean;
        float count = value.count + 1.0f;
        float mean = fma(delta, reciprocal[uint(count)], value.mean);
        volatile float delta_new = element - mean;
        float sigma = fma(delta, delta_new, value.sigma);
        value = Welford{mean, sigma, count};
    }
}
for (ushort offset = 16; offset > 0; offset >>= 1) {
    Welford other{simd_shuffle_down(value.mean, offset), simd_shuffle_down(value.sigma, offset), simd_shuffle_down(value.count, offset)};
    value = merge(value, other, reciprocal);
}
if (lane == 0) { means[warp] = value.mean; sigmas[warp] = value.sigma; counts[warp] = value.count; }
threadgroup_barrier(mem_flags::mem_threadgroup);
for (uint offset = 2; offset > 0; offset >>= 1) {
    if (lane == 0 && warp < offset) {
        Welford other{means[warp + offset], sigmas[warp + offset], counts[warp + offset]};
        value = merge(value, other, reciprocal);
    }
    threadgroup_barrier(mem_flags::mem_threadgroup);
    if (lane == 0 && warp < offset) { means[warp] = value.mean; sigmas[warp] = value.sigma; counts[warp] = value.count; }
    threadgroup_barrier(mem_flags::mem_threadgroup);
}
if (tid == 0) {
    mean_output[row] = value.mean;
    float inverse_width = reciprocal[Width];
    float quotient = value.sigma * inverse_width;
    float remainder = fma(-float(Width), quotient, value.sigma);
    variance_output[row] = fma(inverse_width, remainder, quotient);
}

layernorm_statistics.header:
struct Welford { float mean; float sigma; float count; };
METAL_FUNC Welford merge(Welford current, Welford other, const device float* reciprocal) {
    float count = current.count + other.count;
    if (count == 0.0f) return Welford{0.0f, 0.0f, 0.0f};
    float coef = reciprocal[uint(count)];
    volatile float nA = other.count * coef;
    volatile float nB = current.count * coef;
    volatile float current_mean = nB * current.mean;
    float mean = fma(nA, other.mean, current_mean);
    volatile float delta = current.mean - other.mean;
    volatile float square = delta * delta;
    volatile float scaled = square * other.count;
    volatile float sigma_sum = other.sigma + current.sigma;
    float sigma = fma(nB, scaled, sigma_sum);
    return Welford{mean, sigma, count};
}

layernorm_affine.source:
uint index = thread_position_in_grid.x;
if (index >= uint(Count)) return;
uint row = index / Width, column = index % Width;
volatile float centered = values[index] - means[row];
volatile float normalized = inverses[row] * centered;
float value = fma(weights[column], normalized, bias[column]);
output[index] = value;

stem.source:
uint index = thread_position_in_grid.x;
if (index >= uint(M*N)) return;
int row = index / N, channel = index % N;
float carry = 0.0f;
